Alright Boss — here’s the **easiest, beginner-friendly** C solution for  
👉 **LeetCode 1971: Find if Path Exists in Graph**  

We’ll go with **clear logic**, **simple BFS (Breadth-First Search)** approach — perfect for beginners to understand.

---

## 🧠 Problem Understanding

We’re given:
- `n` nodes (0 to n−1)
- a list of **edges** (connections between nodes)
- a **source** node and a **destination** node

We must check:
> Can we reach `destination` starting from `source`?

---

### 🔍 Example
```
n = 6
edges = [[0,1],[0,2],[3,5],[5,4],[4,3]]
source = 0
destination = 5
```

Graph connections:
```
0 - 1
|
2

3 - 4 - 5
```
There’s **no path** between component `{0,1,2}` and `{3,4,5}` → ❌ **false**

---

## 💡 Concept
We’ll:
1. Build an **adjacency list** (who’s connected to whom)
2. Use **BFS** to explore all reachable nodes starting from `source`
3. If we ever reach `destination`, return `true`
4. If BFS ends and we didn’t reach, return `false`

---

## ✅ Beginner-Friendly BFS Solution in C

```c
#include <stdbool.h>
#include <stdlib.h>

// Simple queue structure for BFS
typedef struct {
    int *data;
    int front, rear;
} Queue;

Queue* createQueue(int size) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->data = (int*)malloc(size * sizeof(int));
    q->front = q->rear = 0;
    return q;
}

void enqueue(Queue* q, int val) {
    q->data[q->rear++] = val;
}

int dequeue(Queue* q) {
    return q->data[q->front++];
}

bool isEmpty(Queue* q) {
    return q->front == q->rear;
}

// Main function
bool validPath(int n, int** edges, int edgesSize, int* edgesColSize, int source, int destination) {
    if (source == destination)
        return true;

    // Step 1: Build adjacency list
    int** graph = (int**)malloc(n * sizeof(int*));
    int* graphSize = (int*)calloc(n, sizeof(int));

    // Count connections to allocate memory
    for (int i = 0; i < edgesSize; i++) {
        graphSize[edges[i][0]]++;
        graphSize[edges[i][1]]++;
    }

    for (int i = 0; i < n; i++)
        graph[i] = (int*)malloc(graphSize[i] * sizeof(int));

    int* idx = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < edgesSize; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        graph[u][idx[u]++] = v;
        graph[v][idx[v]++] = u;
    }

    // Step 2: BFS
    bool* visited = (bool*)calloc(n, sizeof(bool));
    Queue* q = createQueue(n);

    enqueue(q, source);
    visited[source] = true;

    while (!isEmpty(q)) {
        int node = dequeue(q);
        if (node == destination)
            return true;

        for (int i = 0; i < graphSize[node]; i++) {
            int next = graph[node][i];
            if (!visited[next]) {
                visited[next] = true;
                enqueue(q, next);
            }
        }
    }

    return false;
}
```

---

## 🧩 Explanation (Step-by-Step)
1. **Build adjacency list:**  
   Store all nodes connected to each node.  

   Example:
   ```
   0 -> [1, 2]
   1 -> [0]
   2 -> [0]
   3 -> [5, 4]
   4 -> [5, 3]
   5 -> [3, 4]
   ```

2. **Start BFS from `source`:**  
   - Keep a queue to explore neighbors one by one.  
   - Mark visited nodes to avoid revisiting.  
   - If you reach `destination` → return `true`.

3. **If BFS ends** and you never found `destination` → return `false`.

---

## ⚡ Complexity
- **Time:** O(V + E)  
- **Space:** O(V + E)

---

## 🧠 Bonus — Simpler (but less efficient) DFS Recursive Version
If you want even simpler code (but recursion-based):

```c
#include <stdbool.h>
#include <stdlib.h>

bool dfs(int node, int destination, bool* visited, int** graph, int* graphSize) {
    if (node == destination)
        return true;
    visited[node] = true;
    for (int i = 0; i < graphSize[node]; i++) {
        int next = graph[node][i];
        if (!visited[next] && dfs(next, destination, visited, graph, graphSize))
            return true;
    }
    return false;
}

bool validPath(int n, int** edges, int edgesSize, int* edgesColSize, int source, int destination) {
    if (source == destination)
        return true;

    int** graph = (int**)malloc(n * sizeof(int*));
    int* graphSize = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < edgesSize; i++) {
        graphSize[edges[i][0]]++;
        graphSize[edges[i][1]]++;
    }
    for (int i = 0; i < n; i++)
        graph[i] = (int*)malloc(graphSize[i] * sizeof(int));
    int* idx = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < edgesSize; i++) {
        int u = edges[i][0], v = edges[i][1];
        graph[u][idx[u]++] = v;
        graph[v][idx[v]++] = u;
    }

    bool* visited = (bool*)calloc(n, sizeof(bool));
    bool result = dfs(source, destination, visited, graph, graphSize);
    return result;
}
```

---

## 🏁 Summary

| Version | Approach | Easy to Understand | Uses |
|----------|-----------|--------------------|------|
| ✅ BFS | Iterative queue | ⭐⭐⭐⭐⭐ | Best for beginners |
| DFS | Recursion | ⭐⭐⭐ | Conceptual, short code |

---

