## ✅ Beginner-Friendly C Code

```c
#include <stdlib.h>

int* findSmallestSetOfVertices(int n, int** edges, int edgesSize, int* edgesColSize, int* returnSize) {
    int* inDegree = (int*)calloc(n, sizeof(int)); // track in-degree of each node

    // Count in-degrees
    for (int i = 0; i < edgesSize; i++) {
        int to = edges[i][1];
        inDegree[to]++;
    }

    // Nodes with in-degree 0 are the answer
    int* result = (int*)malloc(n * sizeof(int));
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            result[k++] = i;
        }
    }

    free(inDegree);
    *returnSize = k;
    return result;
}
