#include <stdlib.h>

int longestCycle(int* edges, int edgesSize){
    int n = edgesSize;
    int* visited = (int*)calloc(n, sizeof(int)); // 0 = unvisited, 1 = visiting, 2 = fully visited
    int maxCycle = -1;

    for (int i = 0; i < n; i++) {
        if (visited[i] != 0) continue; // already processed

        int node = i;
        int step = 0;
        int* stepMap = (int*)malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) stepMap[j] = -1;

        while (node != -1) {
            if (visited[node] == 2) break;           // fully processed, no cycle here
            if (stepMap[node] != -1) {               // cycle found
                int len = step - stepMap[node];
                if (len > maxCycle) maxCycle = len;
                break;
            }
            stepMap[node] = step++;
            visited[node] = 1;                        // mark visiting
            node = edges[node];
        }

        node = i;
        while (node != -1 && visited[node] == 1) {
            visited[node] = 2;                         // mark fully visited
            node = edges[node];
        }

        free(stepMap);
    }

    free(visited);
    return maxCycle;
}
```

