#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int largestPathValue(char * colors, int** edges, int edgesSize, int* edgesColSize) {
    int n = strlen(colors);

    // Build adjacency list
    int* indegree = (int*)calloc(n, sizeof(int));
    int** adj = (int**)malloc(n * sizeof(int*));
    int* adjSize = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) adj[i] = (int*)malloc(n * sizeof(int));

    for (int i = 0; i < edgesSize; i++) {
        int u = edges[i][0], v = edges[i][1];
        adj[u][adjSize[u]++] = v;
        indegree[v]++;
    }

    // Queue for topological sort
    int* queue = (int*)malloc(n * sizeof(int));
    int front = 0, back = 0;

    for (int i = 0; i < n; i++)
        if (indegree[i] == 0) queue[back++] = i;

    // DP array: dp[i][c] = max count of color c ending at node i
    int** dp = (int**)malloc(n * sizeof(int*));
    for (int i = 0; i < n; i++) {
        dp[i] = (int*)calloc(26, sizeof(int));
    }

    int visitedCount = 0;
    int maxVal = 0;

    while (front < back) {
        int u = queue[front++];
        visitedCount++;
        int cIndex = colors[u] - 'a';
        dp[u][cIndex]++;
        if (dp[u][cIndex] > maxVal) maxVal = dp[u][cIndex];

        for (int i = 0; i < adjSize[u]; i++) {
            int v = adj[u][i];
            for (int c = 0; c < 26; c++) {
                if (dp[u][c] > dp[v][c])
                    dp[v][c] = dp[u][c];
            }
            indegree[v]--;
            if (indegree[v] == 0) queue[back++] = v;
        }
    }

    // Free memory
    for (int i = 0; i < n; i++) free(dp[i]);
    free(dp);
    for (int i = 0; i < n; i++) free(adj[i]);
    free(adj);
    free(adjSize);
    free(indegree);
    free(queue);

    // If there is a cycle
    if (visitedCount != n) return -1;

    return maxVal;
}
```

---

### 🔹 How it Works

1. **Build adjacency list** and track `indegree` for each node.  
2. **Topological sort** using a queue.  
3. **Dynamic programming** (`dp[i][c]`) counts the maximum number of color `c` along paths ending at node `i`.  
4. **Cycle detection**: if not all nodes are visited, return `-1`.  
5. Return the **largest color value** along any path.  

